package com.metaplatform.agent.runs; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.Instant; import java.util.*; public interface AgentRunRepository extends JpaRepository<AgentRunEntity,String> { List<AgentRunEntity> findByTenantIdAndUserIdAndCreatedAtAfterOrderByCreatedAtDesc(String tenantId,String userId,Instant after); Optional<AgentRunEntity> findByRunIdAndStatusIn(String runId,Collection<String> statuses); @Query("SELECT a FROM AgentRunEntity a WHERE a.status IN ('PENDING','RUNNING') AND a.createdAt < :beforeTs") List<AgentRunEntity> findStaleRuns(@Param("beforeTs") Instant beforeTs); }
